/bin/zsh -lc "python3 - <<'PY'
from html.parser import HTMLParser
import re
src=open('<experiment>/start-example/workspace/output/index.html',encoding='utf-8').read()
VOID={'meta','link','br','hr','img','input','source','path','circle','use','area','base','col','embed','track','wbr'}
class P(HTMLParser):
    def __init__(s):
        super().__init__(convert_charrefs=True); s.stack=[]; s.errs=[]
    def handle_starttag(s,t,a):
        if t not in VOID: s.stack.append((t,s.getpos()))
    def handle_startendtag(s,t,a): pass
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.stack: s.errs.append(('extra close',t,s.getpos())); return
        if s.stack[-1][0]==t: s.stack.pop()
        else: s.errs.append(('mismatch',t,s.getpos(),'open='+s.stack[-1][0]))
p=P(); p.feed(src)
print('unclosed:',p.stack)
print('errors:',p.errs)
print('text len:',len(re.sub(r'<["'^>]+>'"','',src).strip()))
# 宽度推算
for vw in (390,1280):
    app_pad=min(max(vw*0.03,12),24)
    panel_pad=min(max(vw*0.03,16),24)
    content=min(vw,960)-2*app_pad
    inner=content-2*panel_pad
    stat=(content-20)/3
    print(f'vw={vw}: content={content:.0f}px panel-inner={inner:.0f}px stat={stat:.1f}px stat-text={stat-8:.1f}px')
PY"

