/bin/zsh -lc "cat > /tmp/dom-test.mjs <<'TESTEOF'
// 用最小 DOM stub 执行真实 output/app.js，验证暂停/继续的交互逻辑（无第三方依赖）
import { readFileSync } from 'node:fs';
import vm from 'node:vm';

const APP = '<experiment>/hud-text/workspace/output/app.js';

class El {
  constructor(id, tag, cls = '') {
    this.id = id; this.tagName = tag.toUpperCase();
    this._classes = new Set(cls.split(/\\s+/).filter(Boolean));
    this.attrs = {}; this._text = ''; this.hidden = false;
    this.listeners = {}; this.children = []; this.parent = null;
    this.classList = {
      add: (...c) => c.forEach(x => this._classes.add(x)),
      remove: (...c) => c.forEach(x => this._classes.delete(x)),
      contains: c => this._classes.has(c),
      toggle: (c, on) => { on === undefined ? (this._classes.has(c) ? this._classes.delete(c) : this._classes.add(c)) : (on ? this._classes.add(c) : this._classes.delete(c)); }
    };
  }
  get textContent() { return this._text; } set textContent(v) { this._text = String(v); }
  setAttribute(k, v) { this.attrs[k] = String(v); }
  getAttribute(k) { return k in this.attrs ? this.attrs[k] : null; }
  addEventListener(t, fn) { (this.listeners[t] ||= []).push(fn); }
  focus() { doc.activeElement = this; }
  blur() { if (doc.activeElement === this) doc.activeElement = doc.body; }
