    const i = part.indexOf(':');
    if (i < 0) continue;
    m[part.slice(0, i).trim()] = part.slice(i + 1).trim();
  }
  return m;
}
// last = 最后一次出现（媒体查询在文件末尾 → 覆盖生效）；first = 基础规则
function rule(sel, which = 'last') {
  const re = new RegExp('(?:"'^|[};])[''^{};]*?'"\\\\b' + sel.replace(/[.*+?"'^${}()|['"\\]\\\\]/g, '\\\\"'$&'"') + '\\\\s*\\\\{(["'^}]*)'"\\\\}', 'g');
